import React from 'react';
import { Outlet, NavLink } from 'react-router-dom';

const TrangChuCuDan = () => {
    // Menu dành riêng cho cư dân dựa trên ảnh
    const menuItems = [
        { name: 'Quản lý thông báo', path: 'thong-bao', icon: '🔔' },
        { name: 'Thông tin cá nhân', path: 'thong-tin', icon: '👤' },
        { name: 'Xem hóa đơn', path: 'hoa-don', icon: '📄' },
        { name: 'Thanh toán (nếu có)', path: 'thanh-toan', icon: '💳' },
        { name: 'Gửi yêu cầu bảo trì', path: 'bao-tri', icon: '🔧' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien', icon: '🚗' },
        { name: 'Đăng ký bãi đỗ xe', path: 'dang-ky-xe', icon: '🅿️' },
    ];

    return (
        <div style={styles.container}>
            {/* Sidebar Cư Dân */}
            <div style={styles.sidebar}>
                <div style={styles.logo}>🏢 A&RMS</div>
                <nav style={styles.nav}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-cu-dan/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navLink,
                                backgroundColor: isActive ? '#333' : 'transparent',
                                borderLeft: isActive ? '4px solid #4caf50' : '4px solid transparent'
                            })}
                        >
                            <span style={styles.icon}>{item.icon}</span> {item.name}
                        </NavLink>
                    ))}
                </nav>
            </div>

            {/* Nội dung bên phải */}
            <div style={styles.content}>
                <header style={styles.header}>
                    <span>Trang chủ / Cư dân</span>
                    <div style={styles.userIcon}>👤 Cư dân</div>
                </header>
                <div style={styles.main}>
                    <Outlet /> {/* Các trang con sẽ hiện ở đây */}
                </div>
            </div>
        </div>
    );
};

const styles = {
    container: { display: 'flex', height: '100vh' },
    sidebar: { width: '260px', backgroundColor: '#1c1c1c', color: '#fff', display: 'flex', flexDirection: 'column' },
    logo: { padding: '20px', fontSize: '22px', fontWeight: 'bold', borderBottom: '1px solid #333', textAlign: 'center' },
    nav: { display: 'flex', flexDirection: 'column', marginTop: '10px' },
    navLink: { padding: '15px 20px', color: '#fff', textDecoration: 'none', fontSize: '14px', transition: '0.3s', display: 'flex', alignItems: 'center' },
    icon: { marginRight: '10px', width: '20px' },
    content: { flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: '#f5f5f5' },
    header: { height: '60px', backgroundColor: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 20px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' },
    main: { padding: '20px', flex: 1, overflowY: 'auto' },
    userIcon: { fontWeight: 'bold' }
};

export default TrangChuCuDan;
